    "modernLink": "現代心理學中的「內控型人格」（Internal Locus of Control）與情緒自律，正與「為仁由己」相通。面對誘惑與外在評價時，不被他人眼光或環境牽著走，能獨立為自己的行為與道德邊界負責，是成熟個體最強大的內核。",
