    "context": "孟子謂宋句踐曰：「子好遊乎？吾語子遊：人知之，亦囂囂；人不知，亦囂囂。」曰：「何如斯可以囂囂矣？」曰：「尊德樂義，則可以囂囂矣。故士窮不失義，達不離道。窮不失義，故士得己焉；達不離道，故民不失望焉。古之人，得志，澤加於民；不得志，脩身見於世。窮則獨善其身，達則兼善天下。」",
    "targetSentence": "窮則獨善其身，達則兼善天下。",
    "vernacular": "孟子對宋句踐說：「...古代的有道君子，得志時，將恩澤推廣普及給廣大人民；不得志時，修養自身品格並展現於世間。處境困頓時，堅守節操修好自身善性；通達順遂時，造福天下使萬民共同向善。」",
    "explanation": "「窮」指仕途受阻、不得志（非單指貧窮）；「達」指仕途亨通、掌握權柄。「獨善其身」是內省自持守住底線，「兼善天下」是推己及人化育蒼生。選項A翻譯典雅精確。",
    "analysis": "這是儒家知識分子面對歷史命運與個人際遇時最成熟、最具彈性的生命典範。儒者既不同於道家的全然避世逃避，亦不同於法家的投機鑽營。無論順境逆境，其道德內核與仁義原則永不動搖：進能兼濟蒼生，退可作育英才、立言垂範。",
    "modernLink": "現代人在職場生涯中難免遭遇行業週期波動與個人職涯低谷。在身處逆境或未獲賞識時（窮），切忌沉淪自暴自棄，應專注於沉澱充電、精進本領與修養心智（獨善其身）；一旦迎來機遇掌舵重大項目時（達），則應全力賦能團隊、回饋社會（兼善天下）。",
