    "context": "項王軍壁垓下，兵少食盡，漢軍及諸侯兵圍之數重。夜聞漢軍四面皆楚歌，項王乃大驚曰：「漢皆已得楚乎？是何楚人之多也！」項王則夜起，飲帳中。有美人名虞，常幸從；駿馬名騅，常騎之。於是項王乃悲歌忼慨，自為詩曰：「力拔山兮氣蓋世，時不利兮騅不逝！騅不逝兮可奈何！虞兮虞兮奈若何！」歌數闋，美人和之。項王泣數行下，左右皆泣，莫能仰視。",
