    "context": "陳勝者，陽城人也，字涉……嘗與人傭耕，輟耕之壟上，悵恨久之，曰：「苟富貴，無相忘。」傭者笑而應曰：「若為傭耕，何富貴也？」陳涉太息曰：「嗟乎，燕雀安知鴻鵠之志哉！」",
