    "vernacular": "唉！在屋簷下跳躍的燕雀小鳥，哪裡懂得展翅高飛萬里的鴻鵠天鵝那宏偉浩大的志向啊！",
    "explanation": "「燕雀」比喻眼光狹隘、隨波逐流的平庸之輩；「鴻鵠」比喻懷抱遠大理想、志在千里的英雄志士。",
