    "difficulty": 2,
    "type": "translation",
    "question": "《戰國策·齊策一》「鄒忌諷齊王納諫」中，鄒忌以妻、妾、客皆私己愛己畏己求己為喻，指出齊王處於更嚴重的蒙蔽之中：「今齊地方千里，百二十城，宮婦左右莫不私王，朝廷之臣莫不畏王，四境之內莫不有求於王。由此觀之，___。」請選出最後一句結論。",
    "options": [
      "王之蔽甚矣",
      "王之名高矣",
      "齊國無敵於天下",
      "王宜罷兵休戰"
    ],
    "correctAnswer": 0,
    "source": {
      "workTitle": "《戰國策》",
      "chapterTitle": "〈齊策一〉",
      "author": "劉向編定",
      "dynasty": "西漢"
    },
    "context": "鄒忌修八尺有餘，而形貌昳麗……旦日，客從外來，與坐談，問之客曰：「吾與徐公孰美？」客曰：「徐公不若君之美也。」明日徐公來，孰視之，自以為不如……暮寢而思之，曰：「吾妻之美我者，私我也；妾之美我者，畏我也；客之美我者，欲有求於我也。」於是入朝見威王，曰：「臣誠知不如徐公美……由此觀之，王之蔽甚矣！」",
    "targetSentence": "由此觀之，王之蔽甚矣！",
    "vernacular": "從這件事情看來，大王您所受到的蒙蔽真是太過嚴重了啊！",
    "explanation": "「蔽」指受蒙蔽、被謊言遮蔽。「王之蔽甚矣」是鄒忌推己及人、以家事諷喻國政的畫龍點睛之筆。",
    "analysis": "鄒忌的進諫藝術被譽為先秦說辯的最高範本。他不直接指責齊王過失，而是從自己比美受阿諛的切身體驗出發，層層類比，使齊威王欣然接受並下令廣開言路（令初下，群臣進諫門庭若市）。",
    "modernLink": "位居高位的領導者身邊常圍繞著阿諛奉承之詞（宮婦左右莫不私王），最容易陷入自我良好的盲區。「王之蔽甚矣」提醒領導者主動建立安全的反饋機制，多聽逆耳忠言。",
    "workId": "zhan-guo-ce",
    "chapterId": "zhan-guo-ce_ch-1"
