    "vernacular": "堆積泥土成為高山，風雨就會在那裡興起；匯聚流水成為深潭，蛟龍就會在那裡滋生；積累善行養成高尚德行，精神智慧自然明澈圓滿，聖人的心境就具備了。所以不一步半步地積累，就無法到達千里之外；不匯集細小細流，就無法匯成江海。駿馬一跳躍，也跨不出十步遠；劣馬拉車走十天，成功在於堅持不停歇。如果雕刻幾下就放棄了，即使腐朽的木頭也折不斷；如果不停雕刻堅持不捨，那麼金屬玉石也能被雕鏤成功。",
    "explanation": "「鍥而不舍，金石可鏤」比喻只要持之以恆、永不放棄，即使是金石這般堅硬之物也能雕刻成功；反之半途而廢則朽木難折。",
    "analysis": "荀子善用鋪排對比，以「騏驥」對比「駑馬」，以「朽木」對比「金石」，層層推進論證「累積」與「恆心」的至上威力。",
    "modernLink": "成功往往不是靠一時的天才爆發，而是依靠日復一日的微小累積與長期主義（Compound effect）。",
