export function getQuestionsByStage(stageId: string): QuestQuestion[] {
  return QUEST_BANK_300.filter((q) => q.stageId === stageId)
}

export function getQuestionById(id: string): QuestQuestion | undefined {
  return QUEST_BANK_300.find((q) => q.id === id)
}

export function getQuestBankStats() {
  const stageStats = QUEST_STAGES.map((s) => ({
    id: s.id,
    title: s.title,
    count: QUEST_BANK_300.filter((q) => q.stageId === s.id).length,
    target: s.targetCount,
  }))
  return {
    total: QUEST_BANK_300.length,
    stageCount: QUEST_STAGES.length,
    stageStats,
  }
}
